1	/**
2	 * Round 30 Benny — `?b30=1` (benny-character-artist, qa/match/06/r30/benny06/NOTES.md). Off (default): nothing in this file
3	 * runs, every material, geometry and shader program is the previous one.
4	 *
5	 * Builds ON benny05 (benny05.ts runs whenever b30 is on: knit / fur / pompom maps baked from approved pixels, beanie seat,
6	 * damped roll) and moves Benny toward the PAINTED Benny of the approved Screen 06 (references/06_crest_the_rinse_arch.png)
7	 * and the r30 storyboard (docs/briefs/2026-11-20-r30/USER_S06_STORYBOARD_R30.png):
8	 *  1. PROPORTIONS: the beanie is about as wide as the upper body (not wider), shorter and sits HIGHER on a taller plush
9	 *     body, so the upper half of the dusty-pink body shows below the thick ribbed cuff (beanie scale about the cuff's
10	 *     bottom centre + raise; body scaled about its bottom so it stays seated in the water).
11	 *  2. FUR UNDER THE CUFF: the shell fur's bald cap (fur.ts uBald) follows the raised cuff, so no bare skin band appears.
12	 *  3. VIEW: a little more forward ride lean, so the rear chase camera sees the knit stripes as level bands and the pompom
13	 *     ON TOP of the beanie (the painting's near-level view) instead of the dome from above.
14	 *  4. FUR LOOK: dusty rose (mean ≈ 230, 90, 175 in the painting) instead of hot pink; shorter, denser, more clumped
15	 *     shells = soft plush, not spiky.
16	 *  5. ARMS: small round fluffy arms at both sides, a little higher / further out like the painting.
17	 * Rig, clips, collision, steering and the game's placement of Benny are unchanged: only meshes / joints inside his own
18	 * scene graph move. Every number can be overridden for QA with `?b30<key>=<value>` (e.g. `&b30hs=0.85`); in `?qa` pages
19	 * `window.__b30.set({...})` re-applies live (tools: qa/match/06/r30/benny06/).
20	 */
21	import * as THREE from 'three';
22	import { flag05 } from '../../vfx/waterRibbon';
23	import type { FurHandle } from './fur';
24	
25	export const BENNY30: boolean = flag05('b30');
26	
27	export interface B30Params {
28	  /** ride lean (deg, + = top forward), replaces the runtime's BENNY_RIDE_PITCH (12.6°) */
29	  pitch: number;
30	  /** beanie: uniform scale about the cuff's bottom centre, extra vertical factor, raise along the body's up (body units) */
31	  hs: number;
32	  hsy: number;
33	  hy: number;
34	  /** beanie: shift toward his back (body units, + = toward the rear camera) */
35	  hz: number;
36	  /** body: width (x, z) and height scale about the body's bottom, extra raise (body units) */
37	  bsx: number;
38	  bsy: number;
39	  by: number;
40	  /** body lower half: superellipse exponent of its profile (GLB 2.8 = round ball; higher = broad flat-based gumdrop),
41	   *  radial gain cap, and an extra width factor that grows toward the base */
42	  bp: number;
43	  bcap: number;
44	  bw: number;
45	  /** fur reaches this far ABOVE the cuff's bottom edge, hidden under the cuff (body units) */
46	  tuck: number;
47	  /** arms: scale, raise, out (body units) */
48	  as: number;
49	  ay: number;
50	  ax: number;
51	  /** body / arm fur: shell length, strand density, clumping (fur.ts uniforms) */
52	  fl: number;
53	  fd: number;
54	  fk: number;
55	  /** body / arm fur colour factor (linear multipliers on the baked albedo) */
56	  fr: number;
57	  fg: number;
58	  fb: number;
59	  /** pompom: scale, colour factor (uniform) */
60	  ps: number;
61	  pk: number;
62	}
63	
64	const DEF: B30Params = {
65	  pitch: 12.6,
66	  hs: 1, hsy: 1, hy: 0, hz: 0,
67	  bsx: 1, bsy: 1, by: 0,
68	  bp: 2.8, bcap: 1.5, bw: 0,
69	  tuck: 0.07,
70	  as: 1, ay: 0, ax: 0,
71	  fl: 0.11, fd: 96, fk: 0.55,
72	  fr: 1, fg: 1, fb: 1,
73	  ps: 1, pk: 1,
74	};
75	
76	/** the chosen look (measured, qa/match/06/r30/benny06/NOTES.md); DEF = benny05 unchanged */
77	const TUNED: Partial<B30Params> = {};
78	
79	const QS: URLSearchParams | null = (() => {
80	  try { return typeof location !== 'undefined' ? new URLSearchParams(location.search) : null; } catch { return null; }
81	})();
82	
83	function initialParams(): B30Params {
84	  const p: B30Params = { ...DEF, ...TUNED };
85	  for (const k of Object.keys(p) as (keyof B30Params)[]) {
86	    const v = parseFloat(QS?.get(`b30${k}`) ?? '');
87	    if (Number.isFinite(v)) p[k] = v;
88	  }
89	  return p;
90	}
91	
92	export interface Benny30Handle {
93	  params: B30Params;
94	  set(p: Partial<B30Params>): B30Params;
95	}
96	
97	/** body bottom (body-local y) of the GLB's pear ball incl. the lower-half stretch (build.ts: skin 0.7, stretch 0.03) */
98	const BODY_BOTTOM = -0.7 * 1.03;
99	/** hat-local cuff bottom (build.ts brimBottom) */
100	const CUFF_Y = 0.22;
101	const SKIN = 0.7;
102	
103	/** Apply to a freshly cloned Benny scene AFTER applyBenny05 (its hat seat / maps / fur are the base). */
104	export function applyBenny30(scene: THREE.Object3D, furs: FurHandle[]): Benny30Handle {
105	  const get = (n: string) => scene.getObjectByName(n);
106	  const hat = get('hat')!;
107	  const pom = get('pom')!;
108	  const armL = get('armL')!, armR = get('armR')!;
109	  const base = {
110	    hatPos: hat.position.clone(), hatScale: hat.scale.clone(),
111	    pomScale: pom.scale.clone(),
112	    armL: armL.position.clone(), armR: armR.position.clone(), armS: armL.scale.clone(),
113	  };
114	  const body = furs.find((f) => f.mesh.name === 'fur_body');
115	  const arms = furs.filter((f) => /^fur_arm/.test(f.mesh.name));
116	  const pomFur = furs.find((f) => f.mesh.name === 'fur_pom');
117	  type U = FurHandle['uniforms'] & { uFurLen: { value: number }; uDensity: { value: number }; uBald: { value: THREE.Vector4 } };
118	  const furCol = new Map<FurHandle, THREE.Color>();
119	  for (const f of [...(body ? [body] : []), ...arms, ...(pomFur ? [pomFur] : [])]) furCol.set(f, f.material.color.clone());
120	  const bald0 = body ? (body.uniforms as U).uBald.value.clone() : null;
121	  const hatUp = bald0 ? new THREE.Vector3(bald0.x, bald0.y, bald0.z).normalize() : new THREE.Vector3(0, 1, 0);
122	
123	  // lower-body reshaping works on a copy of the GLB body geometry (the cached GLB geometry is shared by every clone)
124	  const geo0 = body ? (body.mesh.geometry as THREE.BufferGeometry) : null;
125	  const geo = geo0 ? geo0.clone() : null;
126	  if (body && geo) body.mesh.geometry = geo;
127	  let shapeKey = '';
128	  const reshape = (p: number, cap: number, w: number) => {
129	    if (!geo0 || !geo) return;
130	    const key = `${p},${cap},${w}`;
131	    if (key === shapeKey) return;
132	    shapeKey = key;
133	    const src = geo0.attributes.position as THREE.BufferAttribute;
134	    const dst = geo.attributes.position as THREE.BufferAttribute;
135	    // GLB lower half: r_xz ∝ (1 − t^p0)^(1/p0), t = −y / depth (build.ts flat 0.8 → p0 2.8, cap 1.5)
136	    const p0 = 2.8, depth = -BODY_BOTTOM;
137	    const prof = (t: number, e: number) => Math.pow(Math.max(0, 1 - Math.pow(t, e)), 1 / e);
138	    for (let i = 0; i < src.count; i++) {
139	      const x = src.getX(i), y = src.getY(i), z = src.getZ(i);
140	      let k = 1;
141	      if (y < 0) {
142	        const t = Math.min(-y / depth, 0.9999);
143	        k = Math.min(cap, prof(t, p) / Math.max(1e-4, prof(t, p0))) * (1 + w * t * t);
144	        k = Math.max(1, k);
145	      }
146	      dst.setXYZ(i, x * k, y, z * k);
147	    }
148	    dst.needsUpdate = true;
149	    // normals welded across the UV seam / poles (duplicates by position get one normal: the shell fur stays closed)
150	    geo.computeVertexNormals();
151	    const n = geo.attributes.normal as THREE.BufferAttribute;
152	    const acc = new Map<string, THREE.Vector3>();
153	    const keyOf = (i: number) => `${src.getX(i).toFixed(4)},${src.getY(i).toFixed(4)},${src.getZ(i).toFixed(4)}`;
154	    for (let i = 0; i < n.count; i++) {
155	      const kk = keyOf(i);
156	      const v = acc.get(kk) ?? acc.set(kk, new THREE.Vector3()).get(kk)!;
157	      v.x += n.getX(i); v.y += n.getY(i); v.z += n.getZ(i);
158	    }
159	    for (let i = 0; i < n.count; i++) {
160	      const v = acc.get(keyOf(i))!.clone().normalize();
161	      n.setXYZ(i, v.x, v.y, v.z);
162	    }
163	    n.needsUpdate = true;
164	  };
165	
166	  const params = initialParams();
167	  const apply = () => {
168	    const P = params;
169	    reshape(P.bp, P.bcap, P.bw);
170	    // ---- beanie: scale about the cuff's bottom centre, then raise / shift back ----
171	    const s = P.hs;
172	    hat.scale.set(base.hatScale.x * s, base.hatScale.y * s * P.hsy, base.hatScale.z * s);
173	    const c = new THREE.Vector3(0, CUFF_Y, 0);
174	    const keep = c.clone().sub(c.clone().multiply(new THREE.Vector3(s, s * P.hsy, s))).applyQuaternion(hat.quaternion);
175	    hat.position.copy(base.hatPos).add(keep);
176	    hat.position.y += P.hy;
177	    hat.position.z -= P.hz;
178	    pom.scale.copy(base.pomScale).multiplyScalar(P.ps);
179	    // ---- body: scaled about its bottom, raised ----
180	    if (body) {
181	      body.mesh.scale.set(P.bsx, P.bsy, P.bsx);
182	      body.mesh.position.set(0, BODY_BOTTOM * (1 - P.bsy) + P.by, 0);
183	      // fur tucks under the raised cuff: cuff bottom (body-local, along the body's up) → unscaled skin height → bald dot
184	      const cuffBody = c.clone().multiply(hat.scale).applyQuaternion(hat.quaternion).add(hat.position);
185	      const yUnscaled = (cuffBody.y + P.tuck - body.mesh.position.y) / P.bsy;
186	      const u = body.uniforms as U;
187	      u.uBald.value.w = THREE.MathUtils.clamp(yUnscaled / SKIN, -1, 1.5);
188	      u.uFurLen.value = P.fl;
189	      u.uDensity.value = P.fd;
190	      body.uniforms.uClump.value = P.fk;
191	    }
192	    for (const f of arms) {
193	      const u = f.uniforms as U;
194	      u.uFurLen.value = P.fl * (0.05 / 0.11);
195	      f.uniforms.uClump.value = P.fk;
196	    }
197	    for (const [f, c0] of furCol) {
198	      if (f === pomFur) f.material.color.copy(c0).multiplyScalar(P.pk);
199	      else f.material.color.setRGB(c0.r * P.fr, c0.g * P.fg, c0.b * P.fb);
200	    }
201	    // ---- arms ----
202	    armL.position.copy(base.armL).add(new THREE.Vector3(P.ax, P.ay, 0));
203	    armR.position.copy(base.armR).add(new THREE.Vector3(-P.ax, P.ay, 0));
204	    armL.scale.copy(base.armS).multiplyScalar(P.as);
205	    armR.scale.copy(base.armS).multiplyScalar(P.as);
206	  };
207	  apply();
208	  void hatUp;
209	  const handle: Benny30Handle = {
210	    params,
211	    set(p) { Object.assign(params, p); apply(); return { ...params }; },
212	  };
213	  if (QS && QS.has('qa')) (window as unknown as { __b30?: Benny30Handle }).__b30 = handle;
214	  return handle;
215	}
